import{_ as t,o as r,c as i,a2 as a}from"./chunks/framework.mrTIYZc5.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"DSO Documentation","text":"Native Secret Lifecycle for Docker","tagline":"No Files. No Leaks. No Restarts. Native secret orchestration for Docker.","image":{"src":"/assets/images/logo-transparent.png","alt":"DSO Logo"},"actions":[{"theme":"brand","text":"Introduction","link":"/guide/what-is-dso"},{"theme":"alt","text":"Quickstart","link":"/guide/getting-started"}]},"features":[{"title":"Secret Isolation","details":"All secret values are held in-memory and injected via Unix socket. Zero persistence to disk by design.","icon":"🔒"},{"title":"Unified Configuration","details":"One standard YAML format for AWS, Azure, Huawei Cloud, HashiCorp Vault, and Local File providers.","icon":"🛠️"},{"title":"Smart Rotation","details":"Hot-reload secrets without restarting your services. Atomic updates ensure zero downtime.","icon":"🔄"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),o={name:"index.md"};function s(n,e,c,l,d,u){return r(),i("div",null,[...e[0]||(e[0]=[a('<h2 id="why-dso" tabindex="-1">Why DSO? <a class="header-anchor" href="#why-dso" aria-label="Permalink to &quot;Why DSO?&quot;">​</a></h2><p>Docker Secret Operator (DSO) addresses a critical gap in infrastructure security: the management of sensitive credentials in non-Kubernetes environments. While Kubernetes has a mature ecosystem for secret orchestration, standalone Docker Engine deployments often rely on insecure <code>.env</code> files or manual, friction-heavy procedures.</p><p>DSO provides a <strong>Kubernetes-grade</strong> control loop for Docker Engine. It ensures that secrets are fetched from high-assurance vaults (like AWS Secrets Manager or HashiCorp Vault) and injected directly into target containers with <strong>Zero-Persistence</strong>. This means your secrets never touch the host filesystem, providing a strictly ephemeral and auditable lifecycle.</p><h3 id="core-security-pillars" tabindex="-1">Core Security Pillars: <a class="header-anchor" href="#core-security-pillars" aria-label="Permalink to &quot;Core Security Pillars:&quot;">​</a></h3><ul><li><strong>Zero Persistence</strong>: Secrets reside only in process RAM and target container memory-mapped filesystems.</li><li><strong>Event-Driven</strong>: Immediate reconciliation of container lifecycle events.</li><li><strong>Provider Agnostic</strong>: Standardized interface for AWS, Azure, Huawei Cloud, and HashiCorp Vault.</li><li><strong>Operations First</strong>: Built-in strategy engine for rolling updates and atomic shifts.</li></ul>',5)])])}const g=t(o,[["render",s]]);export{m as __pageData,g as default};
